proc summary data=y2;
    var size invrec mb lev;
    output out=y3 p1= sizep1 invrecp1 mbp1 levp1 p99= sizep99 invrecp99 mbp99 levp99;
run;

data y4;
    if _n_=1 then set y3;
    set y2;
    if size<sizep1 and not missing(size) then size=sizep1;
    if size>sizep99 then size=sizep99;
	if invrec<invrecp1 and not missing(invrec) then invrec=invrecp1;
    if invrec>invrecp99 then invrec=invrecp99;
	if mb<mbp1 and not missing(mb) then mb=mbp1;
    if mb>mbp99 then mb=mbp99;
	if lev<levp1 and not missing(lev) then lev=levp1;
    if lev>levp99 then lev=levp99;
run;

data y5;
  set y4;
  by gvkey year;
  size1 = lag(size);
  invrec1 = lag(invrec);
  nbs1 = lag(nbs);
  ngs1 = lag(ngs);
  mb1 = lag(mb);
  loss1 = lag(loss);
  lev1 = lag(lev);
  merge1 = lag(merge);
  finance1 = lag(finance);
  if first.gvkey then do;
  size1=.;
  invrec1=.;
  nbs1=.;
  ngs1=.;
  mb1=.;
  loss1=.;
  lev1=.;
  merge1=.;
  finance1=.; 
  end;
run;

data y6; 
	set y5;
	if 1989<=fyear<=2010;
run;

